import json, subprocess
from pathlib import Path
ws=Path('/workspace')
rows={r['instance_id']:r for r in map(json.loads, open('corpus/manifest.jsonl'))}
# one instance per repo
seen=set(); mp={}
for iid,r in rows.items():
    if r['repo_key'] in seen: continue
    seen.add(r['repo_key']); mp[r['repo_key']]=iid
for repo_key,iid in mp.items():
    r=rows[iid]
    dst=Path('/tmp/collect')/repo_key
    files=[]
    for n in list(dict.fromkeys(list(r['fail_to_pass'])+list(r['pass_to_pass']))):
        f=n.split('::')[0]
        if f not in files: files.append(f)
    py=ws/'.venvs'/repo_key/'bin/python'
    out=subprocess.run([str(py),'-m','pytest','--disable-warnings','--color=no','--tb=no','--verbose','-rA',*files], cwd=str(dst), capture_output=True, text=True)
    special=[l for l in out.stdout.splitlines() if l.startswith(('XFAIL','XPASS','SKIPPED','ERROR'))]
    print('===',repo_key,'rc',out.returncode,'special',len(special))
    for l in special[:12]: print('   ',l)
EOF

