import json,re
from pathlib import Path
new={r['record_id']:r for r in map(json.loads,open('/tmp/final_run/regrade.jsonl'))}
recs={r['record_id']:r for r in map(json.loads,open('corpus/records.jsonl'))}
def blocks(p):
    out=[]
    for b in re.split(r'(?m)^diff --git ',p)[1:]:
        m=re.match(r'a/(\S+) b/(\S+)',b)
        if not m: continue
        out.append((m.group(1),'new file mode' in b.split('\n@@')[0]))
    return out
def testy(x): return ('test' in x.lower() and x.endswith(('.py','.md')))
reg_set={'conftest.py','pytest.ini','tox.ini','setup.cfg','pyproject.toml','sitecustomize.py','usercustomize.py'}
for k,r in recs.items():
    p=(Path('corpus')/r['patch']).read_text(errors='replace') if r.get('patch') else ''
    bs=blocks(p)
    reg=any(x in reg_set or x.endswith('plugin.py') for x,_ in bs)
    rewrite=any(testy(x) and not isnew for x,isnew in bs)
    addtest=any(testy(x) and isnew for x,isnew in bs)
    if addtest and not reg and not rewrite and new[k]['label']=='unresolved':
        print(k,[x for x,_ in bs],new[k]['notes'],new[k]['failed'][:3])
EOF

