arguments.command:
cd /workspace && python3 - <<'EOF'
import json,collections
from rlgrade.log_parse import normalize_node_id
mans=list(map(json.loads,open('corpus/manifest.jsonl')))
total=0; examples=[]
for m in mans:
    req=m['fail_to_pass']+m['pass_to_pass']
    by=collections.defaultdict(set)
    for n in req: by[normalize_node_id(n)].add(n.split('::')[0])
    coll={k:v for k,v in by.items() if len(v)>1}
    if coll:
        total+=1
        if len(examples)<6: examples.append((m['instance_id'],coll))
print('instances with same-named required tests in different files:',total,'of',len(mans))
for e in examples: print(e)
# prefix collisions: a required id that is a prefix of another required id
pc=0; ex2=[]
for m in mans:
    req=m['fail_to_pass']+m['pass_to_pass']
    for a in req:
        for b in req:
            if a!=b and b.startswith(a):
                pc+=1; ex2.append((m['instance_id'],a,b)); break
print('required-prefix-of-required pairs:',pc)
for e in ex2[:8]: print(e)
EOF

